validator:
function validate(input) {
  const [{ Insurance = [] }] = input;
  const seen = new Set();
  for (const [pid, , , lat, lon] of Insurance) {
    if (pid === null) return 'Every policy needs a pid.';
    if (seen.has(pid)) return `pid ${pid} appears twice.`;
    if (lat === null || lon === null) return `Policy ${pid} needs lat and lon.`;
    seen.add(pid);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  // Small pools make shared tiv_2015 values and shared cities common; values are multiples of 0.25 so they are exact.
  const tivPool = small ? 4 : 600, coordPool = small ? 3 : 40;
  const value = pool => Math.floor(rand() * pool) * 2.5 + (rand() < 0.3 ? 0.25 : 0);
  const coord = () => Math.floor(rand() * coordPool) * 5 + (rand() < 0.2 ? 0.5 : 0);
  const Insurance = [];
  for (let pid = 1; pid <= count; pid++) {
    Insurance.push([pid, value(tivPool), Math.round(rand() * 400) / 4, coord(), coord()]);
  }
  return [{ Insurance }];
}
